CREATE TYPE "EmailStatus" AS ENUM ('QUEUED', 'SENDING', 'SENT', 'FAILED', 'EXPIRED');
CREATE TABLE "AuthenticationSession" ("id" uuid PRIMARY KEY, "userId" uuid NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT, "familyExpiresAt" timestamptz NOT NULL, "revokedAt" timestamptz, "revokedReason" varchar(80), "authVersionAtIssue" integer NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX "AuthenticationSession_userId_revokedAt_idx" ON "AuthenticationSession" ("userId", "revokedAt");
CREATE TABLE "RefreshToken" ("id" uuid PRIMARY KEY, "sessionId" uuid NOT NULL REFERENCES "AuthenticationSession"("id") ON DELETE RESTRICT, "tokenHash" text NOT NULL UNIQUE, "issuedAt" timestamptz NOT NULL DEFAULT now(), "expiresAt" timestamptz NOT NULL, "consumedAt" timestamptz, "replacementId" uuid UNIQUE);
ALTER TABLE "RefreshToken" ADD CONSTRAINT "RefreshToken_replacementId_fkey" FOREIGN KEY ("replacementId") REFERENCES "RefreshToken"("id");
CREATE TABLE "PasswordReset" ("id" uuid PRIMARY KEY, "userId" uuid NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT, "tokenHash" text NOT NULL UNIQUE, "issuedAt" timestamptz NOT NULL DEFAULT now(), "expiresAt" timestamptz NOT NULL, "consumedAt" timestamptz, "supersededAt" timestamptz);
CREATE TABLE "EmailOutbox" ("id" uuid PRIMARY KEY, "resetId" uuid NOT NULL UNIQUE REFERENCES "PasswordReset"("id") ON DELETE RESTRICT, "encryptedPayload" text, "encryptionKeyVersion" integer NOT NULL, "status" "EmailStatus" NOT NULL DEFAULT 'QUEUED', "attemptCount" integer NOT NULL DEFAULT 0, "nextAttemptAt" timestamptz NOT NULL DEFAULT now(), "leaseUntil" timestamptz, "leaseToken" uuid, "lastSafeErrorCode" varchar(80), "createdAt" timestamptz NOT NULL DEFAULT now());
